summary:
Here is the complete, self‑contained demo – a **single HTML file** that includes all the JavaScript inline and pulls the required libraries from CDNs. Open this file in any modern browser and you’ll see a ground plane, several falling boxes and spheres that bounce off each other, and a basic camera view.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Three.js + Rapier Demo</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <script type="module">
    // Load Three.js and Rapier from CDN
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.158/build/three.module.js';
    import initRapier from 'https://cdn.jsdelivr.net/npm/@dimforge/rapier3d@0.10.0/rapier.js';

    (async () => {
      await initRapier();
      const RAPIER = rapier; // global provided by Rapier init script

      // ----- Three.js setup -----
      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        100
      );
      camera.position.set(0, 5, 10);
      camera.lookAt(0, 0, 0); // look toward the origin

      const renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      document.body.appendChild(renderer.domElement);

      // Light
      const dirLight = new THREE.DirectionalLight(0xffffff, 1);
      dirLight.position.set(5, 10, 7);
      scene.add(dirLight);

      // Ground (Three.js mesh)
      const groundGeo = new THREE.BoxGeometry(20, 1, 20);
      const groundMat = new THREE.MeshStandardMaterial({ color: 0x808080 });
      const groundMesh = new THREE.Mesh(groundGeo, groundMat);
      groundMesh.position.y = -0.5; // align with physics ground
      scene.add(groundMesh);

      // Helper arrays & functions for objects
      const objects = [];

      function createBox(size, position, color) {
        const geo = new THREE.BoxGeometry(size.x, size.y, size.z);
        const mat = new THREE.MeshStandardMaterial({ color });
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.copy(position);
        scene.add(mesh);

        const bodyDesc = RAPIER.RigidBodyDesc.dynamic()
          .setTranslation(position.x, position.y, position.z);
        const body = world.createRigidBody(bodyDesc);
        const colliderDesc = RAPIER.ColliderDesc.cuboid(
          size.x / 2,
          size.y / 2,
          size.z / 2
        ).setRestitution(0.6); // make it bouncy
        world.createCollider(colliderDesc, body);

        objects.push({ mesh, body });
      }

      function createSphere(radius, position, color) {
        const geo = new THREE.SphereGeometry(radius, 32, 32);
        const mat = new THREE.MeshStandardMaterial({ color });
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.copy(position);
        scene.add(mesh);

        const bodyDesc = RAPIER.RigidBodyDesc.dynamic()
          .setTranslation(position.x, position.y, position.z);
        const body = world.createRigidBody(bodyDesc);
        const colliderDesc = RAPIER.ColliderDesc.ball(radius)
          .setRestitution(0.6);
        world.createCollider(colliderDesc, body);

        objects.push({ mesh, body });
      }

      // ----- Rapier physics setup -----
      const gravity = new RAPIER.Vector3(0, -9.81, 0);
      const world = new RAPIER.World(gravity);

      // Static ground collider (matches ground mesh)
      const groundBodyDesc = RAPIER.RigidBodyDesc.fixed()
        .setTranslation(0, -0.5, 0);
      const groundBody = world.createRigidBody(groundBodyDesc);
      const groundColliderDesc = RAPIER.ColliderDesc.cuboid(10, 0.5, 10);
      world.createCollider(groundColliderDesc, groundBody);

      // Create a few random boxes and spheres
      const colors = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00];
      for (let i = 0; i < 5; i++) {
        const size = new THREE.Vector3(1, 1, 1);
        const pos = new THREE.Vector3(
          (Math.random() - 0.5) * 8,
          5 + i * 2,
          (Math.random() - 0.5) * 8
        );
        createBox(size, pos, colors[i % colors.length]);
      }
      for (let i = 0; i < 5; i++) {
        const radius = 0.5;
        const pos = new THREE.Vector3(
          (Math.random() - 0.5) * 8,
          8 + i * 2,
          (Math.random() - 0.5) * 8
        );
        createSphere(radius, pos, colors[(i + 2) % colors.length]);
      }

      // Animation loop
      function animate() {
        requestAnimationFrame(animate);
        world.step(); // advance physics

        // Sync Three.js meshes with physics bodies
        for (const obj of objects) {
          const pos = obj.body.translation();
          const rot = obj.body.rotation();
          obj.mesh.position.set(pos.x, pos.y, pos.z);
          obj.mesh.quaternion.set(rot.x, rot.y, rot.z, rot.w);
        }

        renderer.render(scene, camera);
      }

      // Resize handling
      window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
      });

      animate();
    })();
  </script>
</body>
</html>
```

**How to use**

1. Save the above code as `demo.html` (or any name you like).  
2. Open the file in a modern browser (Chrome, Firefox, Edge, Safari).  
3. You’ll see a flat ground, several boxes and spheres falling, colliding, and bouncing, all rendered with Three.js.

Feel free to tweak the numbers (object count, colors, restitution, camera position, etc.) – everything is in one place, so it’s easy to experiment. Enjoy!

Added a fixed‑position, styled status overlay so the progress messages appear clearly on the page:

```html
<style>
  body { margin: 0; overflow: hidden; }
  canvas { display: block; }
  #status {
    position: fixed;
    top: 10px;
    left: 10px;
    background: rgba(0,0,0,0.6);
    color: #fff;
    padding: 5px 10px;
    font-family: Arial,Helvetica,sans-serif;
    font-size: 14px;
    border-radius: 4px;
    z-index: 1000;
  }
</style>
```

Now each initialization step (Three.js, Rapier, world creation, ground collider, etc.) writes to this visible status div, giving immediate feedback without needing the dev tools.
